class Solution:
    def rotateClockwise(self, photo: List[List[int]]) -> List[List[int]]:
        n = len(photo)
        for layer in range(n // 2):
            first, last = layer, n - 1 - layer
            for i in range(first, last):
                off = i - first
                top = photo[first][i]
                photo[first][i] = photo[last - off][first]
                photo[last - off][first] = photo[last][last - off]
                photo[last][last - off] = photo[i][last]
                photo[i][last] = top
        return photo

