code.python:
class Solution:
    def rotateClockwise(self, photo: List[List[int]]) -> List[List[int]]:
        n = len(photo)
        for r in range(n):
            for c in range(r + 1, n):
                photo[r][c], photo[c][r] = photo[c][r], photo[r][c]
        for row in photo:
            row.reverse()
        return photo

code.java:
class Solution {
    public int[][] rotateClockwise(int[][] photo) {
        int n = photo.length;
        for (int r = 0; r < n; r++)
            for (int c = r + 1; c < n; c++) {
                int t = photo[r][c]; photo[r][c] = photo[c][r]; photo[c][r] = t;
            }
        for (int[] row : photo)
            for (int i = 0, j = n - 1; i < j; i++, j--) {
                int t = row[i]; row[i] = row[j]; row[j] = t;
            }
        return photo;
    }
}

