class Solution {
public:
    vector<vector<int>> rotateClockwise(vector<vector<int>>& photo) {
        int n = photo.size();
        for (int r = 0; r < n; r++)
            for (int c = r + 1; c < n; c++) swap(photo[r][c], photo[c][r]);
        for (auto& row : photo) reverse(row.begin(), row.end());
        return photo;
    }
};

